import {track, initAnalytics} from './analytics.js';
import {rankGoal, subscribeAI} from './ai-client.js';
import {normalize,TOPICS,minutes,title,tagEvent,inferTopics,searchable,queryMatch,overlaps,evaluate,buildPlan,makeICS} from './engine.js';
import {icon} from './icons.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{const response=await fetch('./program.json');if(!response.ok)throw Error();data=await response.json()}catch{$('#app').innerHTML='<div class="boot">Program yüklenemedi.<p>Bağlantınızı kontrol edip sayfayı yenileyin.</p><button onclick="location.reload()">Yeniden dene</button></div>';throw Error('Program unavailable')}
const conf={id:'conference',shortName:'COMPASS',yearTag:'',name:{tr:data.title||'Kongre',en:data.title||'Congress'},dates:{tr:'',en:''},venue:{tr:'',en:''},timezone:'UTC',utcOffset:'+00:00',timezoneLabel:{tr:'UTC',en:'UTC'},url:data.source||null,notice:null,...(data.conference||{})};
const L=x=>x&&typeof x==='object'?(x[state.lang]||x.en||x.tr||''):(x||'');
const STORE='conference-compass:'+conf.id;
const slug=String(conf.id).replace(/[^a-z0-9-]+/gi,'-');
const events=data.events.filter(e=>e.valid).map(e=>({...e,tags:tagEvent(e),search:searchable(e)})), byId=Object.fromEntries(events.map(e=>[e.id,e]));
const defaults={goal:'',topics:[],role:'specialist',pace:'balanced',buffer:5,breaks:true,satellites:false,confirmedCourses:[],availability:Object.fromEntries(data.days.map(day=>[day,{enabled:true,start:'08:00',end:'20:00'}]))};
const speakerGroups=Object.values(data.speakers.reduce((all,p)=>{const key=normalize(p.name);if(!all[key])all[key]={...p,sourceProfiles:[p],sessionIds:[...p.sessionIds]};else{all[key].sourceProfiles.push(p);all[key].sessionIds=[...new Set([...all[key].sessionIds,...p.sessionIds])]}return all},{})).sort((a,b)=>a.name.localeCompare(b.name,'tr'));
let stored={};try{stored=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
let state={lang:stored.lang==='en'?'en':'tr',view:'planner',day:data.days[Math.min(1,data.days.length-1)],q:'',topic:'',room:'',type:'',allDays:false,profile:{...defaults,...stored.profile,availability:{...defaults.availability,...stored.profile?.availability}},pinned:(stored.pinned||[]).filter(id=>byId[id]),plan:(stored.plan||[]).filter(id=>byId[id]||String(id).startsWith('custom-')),blocks:stored.blocks||[],excluded:stored.excluded||[],reasons:stored.reasons||{},built:!!stored.built,aiMode:stored.aiMode||'',busy:false};
let aiStatus={phase:'idle'},pendingAction=null;let toastTimer;
const t=(tr,en)=>state.lang==='tr'?tr:en;
const trEvent=e=>e.translations?.[state.lang]?.title?e.translations[state.lang]:e.translations?.tr;
const dayName=(day,long=false)=>new Intl.DateTimeFormat(state.lang==='tr'?'tr-TR':'en-GB',{day:'numeric',month:long?'long':'short',weekday:'long',timeZone:conf.timezone}).format(new Date(day+'T12:00:00'+conf.utcOffset));
const typeName=type=>({session:t('Bilimsel oturum','Scientific session'),abstract:t('Sözel bildiri','Oral abstracts'),course:t('Kurs','Course'),satellite:t('Uydu sempozyumu','Satellite symposium'),ceremony:t('Açılış / kapanış','Opening / closing'),break:t('Mola','Break'),custom:t('Kişisel zaman','Personal time')})[type]||type;
const topicName=id=>{let x=TOPICS.find(t=>t.id===id);return x?.[state.lang]||id};
function save(){try{const {lang,profile,pinned,plan,blocks,excluded,reasons,built,aiMode}=state;localStorage.setItem(STORE,JSON.stringify({lang,profile,pinned,plan,blocks,excluded,reasons,built,aiMode}));return true}catch{toast(t('Tarayıcı kaydetmeye izin vermedi. Bu oturumda devam edebilirsiniz.','Browser storage is unavailable. You can continue in this session.'));return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4800)}
function planItems(){return state.plan.map(id=>byId[id]||state.blocks.find(b=>b.id===id)).filter(Boolean).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start))}
function brand(mobile=false){return `<div class="brand ${mobile?'mobile':''}"><span class="brand-mark">${icon('compass')}</span><div>${esc(conf.shortName)}<span class="brand-year">${esc(conf.yearTag)}</span><small>AI PLANNER</small></div></div>`}
function nav(view,i,tr,en){return `<button data-action="nav" data-view="${view}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${icon(i)}${t(tr,en)}${view==='plan'?`<span class="count">${planItems().filter(e=>e.type!=='break').length}</span>`:''}</button>`}
function render(){document.documentElement.lang=state.lang;const headings={planner:[t('SANA ÖZEL KONGRE','YOUR PERSONAL CONGRESS'),t('Kongreni birlikte planlayalım.','Let’s plan your congress.'),t('Hedeflerini anlat. Sana uygun oturumları, çakışmadan bir araya getirelim.','Tell us your goals. Find the right sessions, without the clashes.')],explore:[t('BİLİMSEL PROGRAM','SCIENTIFIC PROGRAM'),t('Merakının peşinden git.','Follow your curiosity.'),t('Oturumlar, konuşmalar ve bilimsel programın tüm ayrıntıları.','Sessions, talks and every detail of the scientific programme.')],plan:[t('KİŞİSEL PROGRAMIN','YOUR ITINERARY'),t('Senin kongren. Senin ritmin.','Your congress. Your pace.'),t('Seçimlerini sabitle, alternatifleri keşfet, takvimine aktar.','Pin your choices, explore alternatives and export your schedule.')],speakers:[t('BİLİMSEL KADRO','FACULTY'),t('Bilgiyi paylaşan isimler.','Meet the people behind the programme.'),t('Konuşmacı ve moderatörleri bul, oturumlarını incele.','Find speakers and chairs, and explore their sessions.')],about:[t('KAYNAK & ŞEFFAFLIK','SOURCE & TRANSPARENCY'),t('Programın arkasındaki bilgi.','The information behind your plan.'),t('Doğrulanabilir kaynaklar, açık yöntem, gerçek oturumlar.','Traceable sources, a transparent method, real sessions.')]};const h=headings[state.view];
$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<p class="edition"><strong>${esc(L(conf.name))}</strong><br>${esc(L(conf.dates))}<br>${esc(L(conf.venue))}</p><nav class="nav" aria-label="${t('Ana menü','Main navigation')}">${nav('planner','spark','AI Planner','AI Planner')}${nav('explore','grid','Programı keşfet','Explore')}${nav('plan','calendar','Planım','My plan')}${nav('speakers','people','Konuşmacılar','Faculty')}${nav('about','info','Program hakkında','About')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('check')}<strong>${t('Sana ait bir program.','A programme of your own.')}</strong>${t('Hedeflerine uygun oturumlar. Zamanına saygılı bir plan.','Sessions for your goals. A plan that respects your time.')}</div>${conf.url?`<a href="${esc(conf.url)}" target="_blank" rel="noopener">${t('Resmî bilimsel program','Official scientific programme')} ↗</a>`:''}</div></aside><div class="main-shell"><header class="topbar"><div class="mobile-brand">${brand(true)}</div><span class="topbar-title"><b>${esc(L(conf.name))}</b><span class="top-divider"></span>${t('Kişisel kongre asistanın','Your personal congress assistant')}</span><div class="topbar-actions"><button class="language" data-action="language" aria-label="${t('Switch to English','Türkçeye geç')}">${state.lang==='tr'?'TR <span>/ EN</span>':'EN <span>/ TR</span>'}</button><button class="btn" data-action="profile">${icon('settings')}${t('Tercihlerim','Preferences')}</button></div></header><main id="main" class="main-content"><div class="page-heading"><div><div class="eyebrow">${h[0]}</div><h1>${h[1]}</h1><p class="subtitle">${h[2]}</p></div>${state.view==='plan'&&state.plan.length?`<div class="toolbar"><button class="btn" data-action="export">${icon('download')}${t('Takvim','Calendar')}</button><button class="btn" data-action="print">PDF</button></div>`:`<span class="badge neutral">${esc(L(conf.dates)).toLocaleUpperCase(state.lang==='tr'?'tr-TR':'en-GB')}</span>`}</div>${state.view==='planner'?planner():state.view==='explore'?explore():state.view==='plan'?planView():state.view==='speakers'?speakersView():about()}<footer class="footer"><span>Conference Compass · ${t('Açık kaynak','Open source')}${conf.notice?' · '+esc(L(conf.notice)):''}</span><span>${t('Program verisi','Programme snapshot')}: ${new Date(data.fetchedAt).toLocaleDateString(state.lang==='tr'?'tr-TR':'en-GB')} · ${t('Tercihler bu cihazda saklanır','Preferences stay on this device')}</span></footer></main></div></div>`;
if(state.view==='explore')renderResults();if(state.view==='speakers')renderSpeakers();}
function statusText(){if(aiStatus.phase==='idle')return t('AI ilk kullanımda indirilir · yaklaşık 120 MB','AI downloads on first use · about 120 MB');return aiStatus.phase==='ready'?t('Çok dilli AI hazır','Multilingual AI ready'):aiStatus.phase==='error'||aiStatus.phase==='unavailable'?t('Konu eşleştirme modu','Topic matching mode'):t('AI modeli yükleniyor · ilk açılış biraz sürebilir','Loading AI model · first use may take a moment')}
function configForm(modal=false){return `<form id="${modal?'preferences-form':'planner-form'}" data-config><div class="goal-field field"><label for="${modal?'modal-':''}goal">${t('Bu kongreden neyle ayrılmak istiyorsun?','What would you like to take away?')}</label><textarea id="${modal?'modal-':''}goal" name="goal" maxlength="2000" placeholder="${t('Örn. Şok hastasında ultrasonografi kullanımını ve yapay zekânın klinik uygulamalarını öğrenmek istiyorum.','e.g. I want to improve ultrasound use in shock and explore clinical applications of AI.')}">${esc(state.profile.goal)}</textarea><small>${t('Öğrenme hedeflerini Türkçe veya İngilizce yaz. Gün ve saat kısıtlarını aşağıdan belirle.','Write your learning goals in Turkish or English. Set day and time constraints below.')}</small></div>${!modal?`<div class="prompt-examples"><button type="button" data-action="preset" data-preset="clinical">${t('Klinik pratiğimi geliştir','Sharpen my clinical practice')}</button><button type="button" data-action="preset" data-preset="ai">${t('Yapay zekâ & araştırma','AI & research')}</button><button type="button" data-action="preset" data-preset="resident">${t('Asistan öğrenme rotası','Resident learning path')}</button></div>`:''}<div class="field"><span>${t('İlgi alanların','Your interests')}</span><div class="topic-options">${TOPICS.map(x=>`<label class="topic-option"><input type="checkbox" name="topic" value="${x.id}" ${state.profile.topics.includes(x.id)?'checked':''}><span>${x[state.lang]}</span></label>`).join('')}</div></div><div class="form-grid"><div class="field"><label>${t('Mesleki aşama','Career stage')}<select name="role"><option value="specialist" ${state.profile.role==='specialist'?'selected':''}>${t('Uzman hekim','Specialist physician')}</option><option value="resident" ${state.profile.role==='resident'?'selected':''}>${t('Asistan hekim','Resident physician')}</option><option value="academic" ${state.profile.role==='academic'?'selected':''}>${t('Akademisyen / eğitici','Academic / educator')}</option><option value="student" ${state.profile.role==='student'?'selected':''}>${t('Tıp öğrencisi','Medical student')}</option></select></label></div><div class="field"><label>${t('Günlük tempo','Daily pace')}<select name="pace">${[['focused',t('Odaklı · en fazla 4 oturum','Focused · up to 4 sessions')],['balanced',t('Dengeli · en fazla 6 oturum','Balanced · up to 6 sessions')],['full',t('Yoğun · en fazla 10 oturum','Full · up to 10 sessions')]].map(([v,l])=>`<option value="${v}" ${state.profile.pace===v?'selected':''}>${l}</option>`).join('')}</select></label></div></div><details class="advanced" ${modal?'open':''}><summary>${icon('calendar')}${t('Katılım günleri, saatler ve planlama tercihleri','Attendance, hours and planning preferences')}<span>${Object.values(state.profile.availability).filter(x=>x.enabled).length} ${t('gün','days')}</span></summary><div class="advanced-body"><div class="section-title">${t('Hangi gün ve saatlerde katılacaksın?','When will you attend?')}</div>${data.days.map(d=>{let a=state.profile.availability[d];return `<div class="availability"><label><input type="checkbox" name="day-${d}" ${a.enabled?'checked':''}>${dayName(d).split(' ').slice(0,3).join(' ')}</label><input type="time" name="start-${d}" value="${a.start}" aria-label="${d} ${t('başlangıç','start')}"><input type="time" name="end-${d}" value="${a.end}" aria-label="${d} ${t('bitiş','end')}"></div>`}).join('')}<div class="field"><label>${t('Salon değişimleri için süre','Time between different rooms')}<select name="buffer">${[0,5,10,15].map(n=>`<option value="${n}" ${Number(state.profile.buffer)===n?'selected':''}>${n} ${t('dakika','minutes')}</option>`).join('')}</select></label><small>${t('Gerçek yürüyüş süresi ölçülmedi; seçtiğin süre planlama payıdır.','Actual walking times are not measured; this is your planning buffer.')}</small></div><label class="checkbox-row"><input type="checkbox" name="breaks" ${state.profile.breaks?'checked':''}>${t('Uygun aralıklarda resmî molaları koru','Keep published breaks when they fit')}</label><label class="checkbox-row"><input type="checkbox" name="satellites" ${state.profile.satellites?'checked':''}>${t('Uydu sempozyumlarını önerilere dahil et','Include satellite symposia in recommendations')}</label><div class="notice">${t('Kurslar otomatik eklenmez. Kayıt durumunu kontrol ederek programdan kendin ekleyebilirsin.','Courses are not added automatically. Check your registration before adding one from the programme.')}</div></div></details><div class="generate-bar"><div class="ai-status"><span class="ai-status-mark">${icon('spark')}</span><span id="ai-state">${statusText()}</span></div><button type="submit" class="btn primary generate-btn" ${state.busy?'disabled':''}>${icon('spark')}${state.busy?t('Programın hazırlanıyor…','Preparing your plan…'):t('Kişisel programımı oluştur','Build my personal plan')}</button></div><p class="privacy-line">${icon('check')}${t('AI eşleştirmesi tarayıcında çalışır. Hedeflerin dışarı gönderilmez.','AI matching runs in your browser. Your goals are not sent to an external service.')}</p></form>`}
function planner(){return `<div class="planner-layout"><section class="planner-panel"><div class="planner-panel-heading"><span class="ai-orb">${icon('spark')}</span><div><h2>AI Planner</h2><p>${t('İlgi alanlarından uygulanabilir bir programa.','From your interests to a workable itinerary.')}</p></div><span class="badge">${t('KİŞİSEL','PERSONAL')}</span></div>${configForm()}</section><aside class="planner-side"><div class="planner-intro"><span class="eyebrow">${t('PROGRAMIN SENİ BEKLİYOR','YOUR PROGRAMME AWAITS')}</span><h2>${data.days.length} ${t('gün.<br>Senin için doğru seçimler.','days.<br>The right choices for you.')}</h2><div class="planner-metrics"><div><strong>${events.filter(e=>e.type!=='break').length}</strong><span>${t('etkinlik','events')}</span></div><div><strong>${speakerGroups.length}</strong><span>${t('konuşmacı / moderatör','speakers / chairs')}</span></div><div><strong>${events.reduce((n,e)=>n+e.translations.tr.talks.length,0)}</strong><span>${t('alt başlık','subtopics')}</span></div></div><div class="planner-steps"><div><b>01</b><p><strong>${t('Hedefini anlat','Describe your goals')}</strong>${t('AI, oturum içeriklerini hedeflerinle eşleştirir.','AI matches session content to your learning goals.')}</p></div><div><b>02</b><p><strong>${t('Çakışmadan planla','Plan without clashes')}</strong>${t('Saatler, görevlerin ve salon geçişleri birlikte değerlendirilir.','Times, commitments and room changes are checked together.')}</p></div><div><b>03</b><p><strong>${t('Kendine göre düzenle','Make it your own')}</strong>${t('Seçimlerini sabitle veya alternatifleri karşılaştır.','Pin your choices or compare alternatives.')}</p></div></div>${state.built?`<button class="btn primary" data-action="nav" data-view="plan">${icon('calendar')}${t('Mevcut planımı aç','Open my current plan')}</button>`:''}</div><div class="rail-card source-card"><div class="source-heading"><span class="brand-mark">${icon('compass')}</span><div><h3>${t('Yayımlanan program. Uydurma yok.','Published programme. Nothing invented.')}</h3><p>${esc(L(conf.name))}</p></div></div><p class="rail-foot">${t('Oturumlar ve konuşma başlıkları program dosyasından gelir. AI, yeni oturum veya saat üretmez.','Sessions and talk titles come from the programme file. AI never invents sessions or times.')}${conf.notice?' '+esc(L(conf.notice)):''}</p><button class="text-btn" data-action="nav" data-view="explore">${t('Tüm programı incele','Explore the full programme')}</button></div></aside></div>`}
function daysBar(){return `<div class="days">${data.days.map(d=>`<button data-action="day" data-day="${d}" class="day ${!state.allDays&&state.day===d?'active':''}" aria-pressed="${!state.allDays&&state.day===d}"><strong>${d.slice(-2)}</strong><span><b>${new Intl.DateTimeFormat(state.lang==='tr'?'tr-TR':'en-GB',{weekday:'long'}).format(new Date(d+'T12:00:00'))}</b>${new Intl.DateTimeFormat(state.lang==='tr'?'tr-TR':'en-GB',{month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'))}</span></button>`).join('')}</div>`}
function rail(){let items=planItems().filter(e=>e.type!=='break');return `<aside class="right-rail"><div class="compass-card"><div class="compass-symbol"><span class="eyebrow">AI PLANNER</span>${icon('spark')}</div><h2>${t('İlgi alanlarından<br>kişisel programına.','From your interests<br>to your itinerary.')}</h2><p>${t('Hedeflerine uygun oturumları bul. Çakışmaları planlayıcıya bırak.','Find sessions for your goals. Let the planner handle the clashes.')}</p><button class="btn mint" data-action="nav" data-view="planner">${icon('spark')}${t('Planımı oluştur','Build my plan')}</button></div><div class="rail-card"><h3>${t('Planın bir bakışta','Your plan at a glance')}</h3><div class="mini-stats"><div><strong>${items.length}</strong><span>${t('seçili etkinlik','selected events')}</span></div><div><strong>${state.pinned.length}</strong><span>${t('sabitlenmiş oturum','pinned sessions')}</span></div></div><div class="rail-line"></div><p class="rail-foot">${t('Bir oturumu sabitlediğinde, yeniden planlama sırasında seçimin korunur.','Pinned sessions are preserved when you rebuild your plan.')}</p>${items.length?`<button class="text-btn" data-action="nav" data-view="plan">${t('Planımı aç','Open my plan')}</button>`:''}</div><div class="rail-card"><h3>${t('Kaynak bilgisi','Source information')}</h3><p class="rail-foot">${new Date(data.fetchedAt).toLocaleDateString(state.lang==='tr'?'tr-TR':'en-GB')} ${t('tarihli program görüntüsü.','programme snapshot.')}${conf.url?` ${t('Son dakika değişiklikleri için','For last-minute changes, check the')} <a href="${esc(conf.url)}" target="_blank" rel="noopener">${t('resmî programı kontrol et.','official programme.')}</a>`:''}</p></div></aside>`}
function explore(){return `<div class="workspace"><section>${daysBar()}<div class="searchbox">${icon('search')}<input id="search" type="search" value="${esc(state.q)}" placeholder="${t('Konu, konuşmacı veya oturum ara…','Search topics, speakers or sessions…')}" aria-label="${t('Programda ara','Search programme')}"></div><div class="filters"><button class="chip ${state.allDays?'active':''}" data-action="all-days">${t('Tüm günler','All days')}</button><select id="topic-filter" class="filter-select" aria-label="${t('Konu filtresi','Topic filter')}"><option value="">${t('Tüm konular','All topics')}</option>${TOPICS.map(x=>`<option value="${x.id}" ${state.topic===x.id?'selected':''}>${x[state.lang]}</option>`).join('')}</select><select id="room-filter" class="filter-select" aria-label="${t('Salon filtresi','Room filter')}"><option value="">${t('Tüm salonlar','All rooms')}</option>${Object.values(data.rooms).map(r=>`<option ${state.room===r?'selected':''}>${r}</option>`).join('')}</select><select id="type-filter" class="filter-select" aria-label="${t('Etkinlik türü','Event type')}"><option value="">${t('Tüm etkinlikler','All events')}</option>${['session','abstract','course','satellite','ceremony','break'].map(x=>`<option value="${x}" ${state.type===x?'selected':''}>${typeName(x)}</option>`).join('')}</select>${state.q||state.topic||state.room||state.type?`<button class="text-btn" data-action="clear-filters">${t('Temizle','Clear')}</button>`:''}</div><div id="results"></div></section>${rail()}</div>`}
function filteredEvents(){return events.filter(e=>(state.allDays||e.date===state.day)&&(!state.q||queryMatch(e.search,state.q))&&(!state.topic||e.tags.includes(state.topic))&&(!state.room||e.room===state.room)&&(state.type?e.type===state.type:e.type!=='break'))}
function renderResults(){let rows=filteredEvents();$('#results').innerHTML=`<div class="result-line" role="status"><span><strong>${rows.length} ${t('etkinlik','events')}</strong> · ${state.allDays?t('Tüm günler','All days'):dayName(state.day)}</span><span>${t('Saate göre','By time')}</span></div>${rows.length?grouped(rows):empty(t('Bu seçimle eşleşen oturum yok.','No matching sessions.'),t('Başka bir konu ara veya filtreleri genişlet.','Try another topic or broaden your filters.'),'clear-filters',t('Filtreleri temizle','Clear filters'))}`}
function grouped(rows,plan=false){return [...new Set(rows.map(e=>e.date))].map(d=>`${(state.allDays||plan)?`<h2 class="day-section-title">${dayName(d,true)}</h2>`:''}${[...new Set(rows.filter(e=>e.date===d).map(e=>e.start))].map(time=>`<div class="time-group"><div class="time-label">${time}</div><div class="session-stack">${rows.filter(e=>e.date===d&&e.start===time).map(e=>card(e,plan)).join('')}</div></div>`).join('')}`).join('')}
function reasonText(e){const r=state.reasons[e.id]||evaluate(e,state.profile);if(r.reason==='pinned')return t('Senin seçimin · yeniden planlamada korunur.','Your choice · preserved when replanning.');if(r.reason==='custom')return t('Sana ayrılmış zaman.','Time reserved for you.');if(r.reason==='topics')return t('Hedeflerinle eşleşiyor: ','Matches your interests: ')+(r.matched||[]).map(topicName).join(', ');if(r.reason==='semantic')return t('AI, oturum içeriğiyle öğrenme hedefin arasında anlamsal yakınlık buldu.','AI found semantic similarity between this session and your learning goal.');if(r.reason==='goal')return t('Yazdığın hedefteki kavramlarla eşleşiyor.','Matches concepts in your written goal.');if(r.reason==='ceremony')return t('Kongrenin ortak açılış / kapanış programı.','Part of the shared opening / closing programme.');return t('Uygun zaman aralığında tamamlayıcı bir oturum.','A complementary session within your availability.')}
function card(e,plan=false){if(e.type==='custom')return `<article class="custom-block"><div class="card-top"><span class="badge neutral">${typeName('custom')}</span><button class="icon-btn" data-action="remove-block" data-id="${e.id}" aria-label="${t('Kişisel zamanı kaldır','Remove personal time')}">${icon('close')}</button></div><h3>${esc(e.title)}</h3><p>${e.start}–${e.end} · ${t('Planlamada korunur','Protected when planning')}</p></article>`;let d=trEvent(e),inPlan=state.plan.includes(e.id),pinned=state.pinned.includes(e.id);if(e.type==='break')return `<div class="break-card">${icon('coffee')}<button data-action="detail" data-id="${e.id}">${esc(d.title)}</button><span>${e.start}–${e.end}</span></div>`;return `<article class="session-card ${inPlan?'in-plan':''}" data-session="${e.id}"><div class="card-top"><div class="card-meta"><span class="room">${icon('map')}${esc(e.room)}</span><span>${e.start}–${e.end}</span>${e.type==='course'?`<span class="badge amber">${t('Kayıt gerekliliğini kontrol et','Check registration')}</span>`:''}</div><div class="card-actions">${pinned?`<span class="pin-badge">${icon('pin')}${t('Sabit','Pinned')}</span>`:''}<button class="icon-btn ${inPlan?'saved':''}" data-action="${inPlan?'remove':'add'}" data-id="${e.id}" aria-label="${esc(d.title)}: ${inPlan?t('planımdan çıkar','remove from my plan'):t('planıma ekle','add to my plan')}" title="${inPlan?t('Planımdan çıkar','Remove from my plan'):t('Planıma ekle','Add to my plan')}">${icon(inPlan?'check':'plus')}</button></div></div><button class="session-title" data-action="detail" data-id="${e.id}"><h3>${esc(d.title)}</h3></button><p class="session-speakers">${esc(d.chairs||d.people.map(p=>p.name).join(' · ')||t('Konuşmacı bilgisi henüz yayımlanmamış.','Speakers not yet published.'))}</p><div class="card-bottom"><div class="tags"><span class="tag">${typeName(e.type)}</span>${d.talks.length?`<span class="tag">${d.talks.length} ${t('alt başlık','subtopics')}</span>`:''}</div><div class="card-actions">${plan?`<button class="icon-btn ${pinned?'saved':''}" data-action="pin" data-id="${e.id}" aria-label="${pinned?t('Sabitlemeyi kaldır','Unpin'):t('Sabitle','Pin')}" title="${pinned?t('Sabitlemeyi kaldır','Unpin'):t('Sabitle','Pin')}">${icon('pin')}</button><button class="text-btn" data-action="alternatives" data-id="${e.id}">${t('Alternatifler','Alternatives')}</button>`:`<button class="text-btn" data-action="detail" data-id="${e.id}">${t('Ayrıntılar','Details')}</button>`}</div></div>${plan?`<div class="reason">${icon('spark')}<span>${esc(reasonText(e))}</span></div>`:''}</article>`}
function empty(h,p,action,label){return `<div class="empty">${icon('compass')}<h3>${h}</h3><p>${p}</p>${action?`<button class="btn primary" data-action="${action}" ${action==='nav'?'data-view="planner"':''}>${label}</button>`:''}</div>`}
function planView(){let items=planItems();if(!items.length)return empty(t('Kongren henüz planlanmadı.','Your congress is waiting to be planned.'),t('AI Planner ile hedeflerine uygun bir program oluştur veya keşfettiğin oturumları kendin ekle.','Build a personal schedule with AI Planner, or add sessions as you explore.'),'nav',t('AI Planner’ı aç','Open AI Planner'));const sessions=items.filter(e=>e.type!=='break');return `<div class="plan-banner"><div><div class="plan-summary"><span>${icon('check')} <strong>${t('Çakışmasız program','Conflict-free plan')}</strong></span><span>${sessions.length} ${t('etkinlik','events')} · ${new Set(items.map(e=>e.date)).size} ${t('gün','days')}</span></div><p>${t('Saat dilimi','Time zone')}: ${esc(L(conf.timezoneLabel))}. ${state.aiMode==='local-semantic'?t('Yerel AI eşleştirmesi kullanıldı.','Local AI matching was used.'):t('Konu eşleştirmesi kullanıldı.','Topic matching was used.')}</p></div><div class="toolbar"><button class="btn small" data-action="block">${icon('plus')}${t('Kişisel zaman','Personal time')}</button><button class="btn small" data-action="profile">${icon('settings')}${t('Yeniden planla','Replan')}</button></div></div><div class="workspace"><section>${grouped(items,true)}</section>${rail()}</div>`}
function speakersView(){return `<div class="searchbox">${icon('search')}<input id="speaker-search" type="search" value="${esc(state.q)}" placeholder="${t('İsimle konuşmacı veya moderatör ara…','Search speakers or chairs by name…')}" aria-label="${t('Konuşmacı ara','Search faculty')}"></div><div id="speaker-results"></div>`}
function renderSpeakers(){const people=speakerGroups.filter(p=>queryMatch(normalize(p.name),state.q));$('#speaker-results').innerHTML=`<div class="result-line"><span><strong>${people.length}</strong> ${t('konuşmacı / moderatör','speakers / chairs')}</span></div><div class="speakers-grid">${people.map(p=>`<button class="speaker-card" data-action="speaker" data-id="${p.id}"><span class="initials">${p.name.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('')}</span><h3>${esc(p.name)}</h3><p>${p.sessionIds.length} ${t('oturumda yer alıyor','sessions')}</p></button>`).join('')}</div>${people.length?'':empty(t('İsim bulunamadı.','No matching name.'),t('Türkçe karakter kullanmadan da arayabilirsin.','You can search without diacritics.'))}`}
function about(){const counts=events.reduce((a,e)=>(a[e.type]=(a[e.type]||0)+1,a),{});return `<div class="about-grid"><article class="about-card"><h3>${t('Programın eksiksiz görüntüsü','A complete snapshot of the programme')}</h3><span class="source-stat">${events.length} ${t('geçerli kayıt','valid entries')}</span><p>${data.days.length} ${t('gün','days')} · ${Object.keys(data.rooms).length} ${t('salon / alan','rooms / areas')} · ${speakerGroups.length} ${t('konuşmacı / moderatör','speakers / chairs')}</p><ul>${Object.entries(counts).map(([type,n])=>`<li>${typeName(type)}: ${n}</li>`).join('')}</ul><p>${data.speakers.length} ${t('konuşmacı profili, aynı yazılan adlara göre','faculty profiles are grouped under')} ${speakerGroups.length} ${t('başlıkta gruplandı; özgün kayıtlar korundu.','exact-name headings; all source records are preserved.')}</p>${conf.url?`<a href="${esc(conf.url)}" target="_blank" rel="noopener">${t('Resmî bilimsel programı aç','Open the official programme')}</a>`:''}</article><article class="about-card"><h3>${t('AI nasıl çalışıyor?','How does AI work?')}</h3><p>${t('Çok dilli MiniLM modeli, yazdığın öğrenme hedefi ile resmî oturum içeriklerinin anlamsal yakınlığını hesaplar. Bu bir sohbet modeli değildir. Konu tercihleriyle birlikte öneri puanı oluşturur; saat, salon geçişi ve sabit görevleri ayrı bir planlama algoritması kontrol eder.','A multilingual MiniLM model measures semantic similarity between your learning goal and official session content. This is not a chat model. It combines this with topic preferences; a separate scheduling algorithm checks time, room transitions and pinned commitments.')}</p><p style="margin-top:12px">${t('AI çalışmadığında konu eşleştirmesine geçilir ve bu durum açıkça gösterilir. Öneriler eğitim düzeyi veya bilimsel kalite puanı değildir.','When AI is unavailable, topic matching is used and labelled. Recommendations are not ratings of educational level or scientific quality.')}</p><div class="notice" style="margin-top:15px">${statusText()} · MiniLM-L12-v2</div></article><article class="about-card"><h3>${t('Kaynakta yayımlanmayan bilgiler','Information not published in the source')}</h3><p>${t('Alt konuşma süreleri kaynakta ayrı verilmediğinde oturumun tamamı planlanır. Eksik özet, dil, kontenjan ve kayıt bilgileri tahmin edilmez. İçerik etiketleri, başlık ve açıklamalardan otomatik türetilir.','If individual talk times are not published, the whole session is scheduled. Missing abstracts, language, capacity and registration details are not guessed. Topic tags are derived automatically from titles and descriptions.')}</p>${data.sourceIssues?.length?`<p style="margin-top:12px">${t('Geçersiz kaynak kayıtları program dışında tutuldu','Invalid source records were excluded')}: ${data.sourceIssues.map(x=>esc(x.id)).join(', ')}</p>`:''}<p style="margin-top:12px">${t('Son veri çekimi','Snapshot captured')}: ${new Date(data.fetchedAt).toLocaleString(state.lang==='tr'?'tr-TR':'en-GB')}</p><button class="text-btn" data-action="download-data">${t('Tam program verisini indir (JSON)','Download the full programme data (JSON)')}</button></article><article class="about-card"><h3>${t('Verilerin ve kaydetme','Your data and saving')}</h3><p>${t('Tercihlerin ve kişisel planın bu tarayıcıda saklanır. AI hesabı veya API anahtarı gerekmez. Bu sürümde e-posta gönderimi, bulut senkronizasyonu veya canlı program güncellemesi yoktur.','Your preferences and plan are stored in this browser. No AI account or API key is needed. This version does not send emails, sync to the cloud or update the programme live.')}</p><p style="margin-top:12px">${t('Çevrimdışı olarak son açılan programı ve kaydedilen planı görüntüleyebilirsin. AI modeli ilk kullanımda indirilir ve tarayıcı önbelleğinde tutulur; önbellek yoksa internet gerekir.','You can view the last opened programme and saved plan offline. The AI model downloads on first use and is cached in your browser; an internet connection is needed if it is not cached.')}</p><button class="btn small" style="margin-top:18px" data-action="reset">${t('Bu cihazdaki planı sıfırla','Reset the plan on this device')}</button></article></div>`}
function openDialog(id,html){const d=$('#'+id);d.innerHTML=html;if(!d.open)d.showModal();}
function closeDialog(id){$('#'+id).close()}
function dialogHeader(h){return `<header class="dialog-header"><h2>${h}</h2><button class="icon-btn" data-action="close-dialog" aria-label="${t('Kapat','Close')}">${icon('close')}</button></header>`}
function detail(id){const e=byId[id];if(!e)return;track('session_view',{session_id:id});const d=trEvent(e);openDialog('detail',`${dialogHeader(esc(d.title))}<div class="dialog-body"><div class="detail-meta"><span>${dayName(e.date,true)}</span><span>${e.start}–${e.end}</span><span>${esc(e.room)}</span></div><span class="badge neutral">${typeName(e.type)}</span>${d.chairs?`<div class="detail-section"><p class="detail-raw">${esc(d.chairs)}</p></div>`:''}${e.type==='course'?`<div class="notice warn detail-section">${t('Bu kursa kayıt gerekip gerekmediğini organizasyondan doğrula. Plana eklemek kurs kaydı oluşturmaz.','Confirm registration requirements with the organiser. Adding this course does not register you.')}</div>`:''}<div class="detail-section"><h3>${t('Oturum içeriği','Session content')}</h3>${d.talks.length?d.talks.map((x,i)=>`<div class="talk"><span class="talk-number">${i+1}</span><div><h4>${esc(x.title)}</h4>${x.speaker?`<p>${esc(x.speaker)}</p>`:''}</div></div>`).join(''):d.description?`<p class="detail-raw">${esc(d.description)}</p>`:`<p class="rail-foot">${t('Kaynakta ayrıntılı konuşma içeriği henüz yayımlanmamış.','Detailed talk content has not yet been published in the source.')}</p>`}${d.talks.length?`<p class="rail-foot" style="margin-top:15px">${t('Alt konuşmaların ayrı saatleri belirtilmediği için oturum bütün olarak planlanır.','Individual talk times are not published; the session is planned as a whole.')}</p>`:''}</div>${d.people.length?`<div class="detail-section"><h3>${t('Konuşmacılar & moderatörler','Speakers & chairs')}</h3>${d.people.map(p=>`<button class="person-pill" data-action="speaker" data-id="${p.id}">${icon('people')}${esc(p.name)}</button>`).join('')}</div>`:''}${e.tags.length?`<div class="detail-section"><h3>${t('İçerikten türetilen konular','Topics derived from content')}</h3><div class="tags">${e.tags.map(id=>`<span class="tag">${topicName(id)}</span>`).join('')}</div>`:''}<div class="detail-section">${d.sourceUrl?`<a class="text-btn" href="${esc(d.sourceUrl)}" target="_blank" rel="noopener">${t('Kaynak oturum ayrıntısını aç','Open the source session detail')} ↗</a>`:''}<details style="margin-top:15px"><summary class="rail-foot">${t('Kaynak metninin tamamı','Complete source text')}</summary><p class="detail-raw">${esc(d.detailText)}</p></details></div></div><footer class="dialog-footer"><button class="btn" data-action="alternatives" data-id="${id}">${t('Aynı saatte neler var?','What else is on?')}</button><button class="btn primary" data-action="${state.plan.includes(id)?'remove':'add'}" data-id="${id}">${icon(state.plan.includes(id)?'check':'plus')}${state.plan.includes(id)?t('Planımdan çıkar','Remove from my plan'):t('Planıma ekle ve sabitle','Add and pin to my plan')}</button></footer>`)}
function speakerDetail(id){const p=speakerGroups.find(x=>x.sourceProfiles.some(y=>y.id===id));if(!p)return;openDialog('detail',`${dialogHeader(esc(p.name))}<div class="dialog-body"><div class="notice">${p.sessionIds.length} ${t('oturumda konuşmacı veya moderatör olarak yer alıyor.','sessions as speaker or chair.')}</div><div class="detail-section">${p.sessionIds.map(id=>byId[id]).filter(Boolean).map(e=>`<p class="rail-foot" style="margin:16px 0 6px">${dayName(e.date,true)}</p>${card(e)}`).join('')}</div><details style="margin-top:20px"><summary class="rail-foot">${t('Kaynakta yayımlanan profil metni','Published source profile')}</summary><p class="detail-raw">${esc(p.sourceProfiles.map(x=>x.translations[state.lang]?.text||x.translations.tr.text).join('\n\n'))}</p></details></div>`)}
function alternatives(id){const e=byId[id];let alt=events.filter(x=>x.id!==id&&x.type!=='break'&&overlaps(e,x,0)).sort((a,b)=>evaluate(b,state.profile).score-evaluate(a,state.profile).score);openDialog('detail',`${dialogHeader(t('Aynı zaman, farklı seçenekler','Same time, different possibilities'))}<div class="dialog-body"><div class="notice">${esc(title(e,state.lang))}<br>${dayName(e.date)} · ${e.start}–${e.end}</div><p class="rail-foot" style="margin:15px 0">${t('Yeni bir seçim, çakışan mevcut oturumları değiştirmek için onayını ister.','A new selection will ask before replacing conflicting sessions.')}</p><div class="session-stack">${alt.map(x=>card(x)).join('')||t('Bu saat aralığında başka oturum yok.','No other sessions in this time interval.')}</div></div>`)}
function showConfirmation(h,body,fn,label=t('Onayla','Confirm')){pendingAction=fn;openDialog('confirm',`${dialogHeader(h)}<div class="dialog-body">${body}</div><footer class="dialog-footer"><button class="btn" data-action="cancel-confirm">${t('Vazgeç','Cancel')}</button><button class="btn primary" data-action="confirm-action">${label}</button></footer>`)}
function addSession(id,confirmed=false){const e=byId[id];if(!e)return;const av=state.profile.availability[e.date];if(!av?.enabled||e.start<av.start||e.end>av.end){toast(t('Bu oturum katılım saatlerinin dışında. Tercihlerinden gün ve saatleri güncelle.','This session is outside your availability. Update attendance in Preferences.'));return}if(e.type==='course'&&!confirmed&&!state.profile.confirmedCourses.includes(id)){showConfirmation(t('Kurs kaydını kontrol et','Check course registration'),`<p>${t('Plana eklemek kayıt oluşturmaz. Bu kurs için katılım koşullarını kontrol ettin mi?','Adding this course does not register you. Have you checked attendance requirements?')}</p>`,()=>{state.profile.confirmedCourses.push(id);addSession(id,true)},t('Kontrol ettim, plana ekle','Checked, add to plan'));return}const conflicts=planItems().filter(x=>x.id!==id&&overlaps(x,e,Number(state.profile.buffer)));if(conflicts.some(x=>x.type==='custom')){toast(t('Kişisel zaman bloğunla çakışıyor. Önce bu zaman bloğunu düzenle veya kaldır.','This conflicts with personal time. Remove or change that block first.'));return}const commit=()=>{let removed=conflicts.map(x=>x.id);state.plan=state.plan.filter(x=>!removed.includes(x));state.pinned=state.pinned.filter(x=>!removed.includes(x));state.excluded=state.excluded.filter(x=>x!==id);if(!state.plan.includes(id))state.plan.push(id);if(!state.pinned.includes(id))state.pinned.push(id);state.reasons[id]={reason:'pinned'};track('session_added',{session_id:id});state.built=true;save();closeDialog('detail');render();toast(t('Oturum planına eklendi ve sabitlendi.','Session added and pinned.'))};if(conflicts.length){showConfirmation(t('Çakışmayı birlikte çözelim','Resolve this clash'),`<p>${t('Bu seçim aşağıdaki etkinliklerin yerine geçecek. Sabitlenmiş seçimler de listede belirtilir.','This choice will replace the following events. Pinned choices are marked.')}</p>${conflicts.map(x=>`<div class="conflict-item"><strong>${esc(title(x,state.lang))}</strong><span>${x.start}–${x.end} · ${esc(x.room)} ${state.pinned.includes(x.id)?'· '+t('SABİT','PINNED'):''}</span></div>`).join('')}`,commit,t('Bu seçimi kullan','Use this choice'))}else commit()}
function removeSession(id){track('session_removed',{session_id:id});state.plan=state.plan.filter(x=>x!==id);state.pinned=state.pinned.filter(x=>x!==id);state.excluded=[...new Set([...state.excluded,id])];save();closeDialog('detail');render();toast(t('Oturum çıkarıldı; yeniden planlamada önerilmeyecek.','Removed; it will be excluded when replanning.'))}
function readForm(form){let fd=new FormData(form);const p={...state.profile,goal:String(fd.get('goal')||'').trim(),topics:fd.getAll('topic'),role:fd.get('role'),pace:fd.get('pace'),buffer:Number(fd.get('buffer')),breaks:fd.has('breaks'),satellites:fd.has('satellites'),availability:{}};for(const day of data.days){let a={enabled:fd.has('day-'+day),start:fd.get('start-'+day),end:fd.get('end-'+day)};if(a.enabled&&(!a.start||!a.end||a.start>=a.end))throw Error(t('Başlangıç saati bitişten önce olmalı: ','Start must be before end: ')+dayName(day));p.availability[day]=a}if(!Object.values(p.availability).some(a=>a.enabled))throw Error(t('En az bir katılım günü seç.','Select at least one attendance day.'));return p}
async function generate(form){if(state.busy)return;let p;try{p=readForm(form)}catch(e){toast(e.message);return}state.busy=true;track('planner_started');const btn=form.querySelector('[type=submit]');btn.disabled=true;btn.innerHTML=icon('spark')+t('Hedeflerin eşleştiriliyor…','Matching your goals…');let mode='topics';p.semantic={};const query=[p.goal,...p.topics.map(topicName)].filter(Boolean).join('. ');if(query){try{const result=await rankGoal(query);p.semantic=result.scores;mode=result.mode}catch{}}
const result=buildPlan(events,p,state.pinned,state.blocks,state.excluded);state.busy=false;btn.disabled=false;btn.innerHTML=icon('spark')+t('Kişisel programımı oluştur','Build my personal plan');if(!result.ok){track('planner_failed');const msg=result.errors.map(x=>x.type==='availability'?`${x.a.type==='custom'?x.a.title:title(x.a,state.lang)}: ${t('katılım saatleri dışında','outside attendance hours')}`:`${x.a.type==='custom'?x.a.title:title(x.a,state.lang)} / ${x.b.type==='custom'?x.b.title:title(x.b,state.lang)}: ${t('çakışma veya geçiş süresi sorunu','time clash or transition conflict')}`).join('\n');openDialog('confirm',`${dialogHeader(t('Sabit seçimleri kontrol et','Check pinned choices'))}<div class="dialog-body"><p class="detail-raw">${esc(msg)}</p><p class="rail-foot">${t('Tercihlerini genişlet veya Planım bölümünden ilgili sabitlemeyi kaldır. Mevcut planın değiştirilmedi.','Broaden your attendance or unpin the relevant sessions in My plan. Your existing plan is unchanged.')}</p></div>`);return}track('planner_completed',{mode,event_count:result.items.filter(e=>e.type!=='break').length});state.profile=p;state.plan=result.items.map(e=>e.id);state.reasons=result.reasons;state.aiMode=mode;state.built=true;state.view='plan';save();closeDialog('profile');render();window.scrollTo({top:0,behavior:'smooth'});toast(mode==='local-semantic'?t('AI hedeflerini eşleştirdi. Çakışmasız programın hazır.','AI matched your goals. Your conflict-free plan is ready.'):t('Konu eşleştirmesiyle programın hazır.','Your plan is ready using topic matching.'))}
function profileDialog(){openDialog('profile',`${dialogHeader(t('Programını sana uyduralım','Make the programme work for you'))}<div class="dialog-body">${configForm(true)}</div>`)}
function blockDialog(){openDialog('profile',`${dialogHeader(t('Kendine zaman ayır','Reserve personal time'))}<form id="block-form"><div class="dialog-body"><div class="field"><label for="block-title">${t('Başlık','Title')}</label><input id="block-title" name="title" maxlength="120" required placeholder="${t('Örn. Konuşma hazırlığı','e.g. Talk preparation')}"></div><div class="field"><label for="block-day">${t('Gün','Day')}</label><select id="block-day" name="day">${data.days.map(d=>`<option value="${d}">${dayName(d)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="block-start">${t('Başlangıç','Start')}</label><input id="block-start" name="start" type="time" value="12:35" required></div><div class="field"><label for="block-end">${t('Bitiş','End')}</label><input id="block-end" name="end" type="time" value="14:00" required></div></div><p class="rail-foot">${t('Bu aralık yeniden planlamada korunur.','This period is protected when you replan.')}</p></div><footer class="dialog-footer"><button class="btn primary" type="submit">${t('Zamanı ayır','Reserve time')}</button></footer></form>`)}
function download(name,content,type){let blob=new Blob([content],{type});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function applyPreset(name,form){const values={clinical:[t('Şok, sepsis, ultrasonografi ve havayolu yönetiminde klinik pratiğimi geliştirmek istiyorum.','I want to improve clinical care in shock, sepsis, ultrasound and airway management.'),['critical','us','airway']],ai:[t('Yapay zekânın acil tıpta klinik uygulamaları, kanıta dayalı tıp ve araştırma yöntemleriyle ilgileniyorum.','I am interested in clinical AI in emergency medicine, evidence-based practice and research.'),['ai','research']],resident:[t('Acil tıp asistanıyım. Resüsitasyon, travma ve temel ultrasonografi becerilerimi geliştirmek istiyorum.','I am an emergency medicine resident. I want to improve resuscitation, trauma and ultrasound skills.'),['cardio','trauma','us']]};let [goal,topics]=values[name];form.elements.goal.value=goal;for(const c of form.querySelectorAll('[name=topic]'))c.checked=topics.includes(c.value);if(name==='resident')form.elements.role.value='resident'}
function listen(type,handler){for(const root of document.querySelectorAll('#app,dialog'))root.addEventListener(type,handler,true)}
listen('submit',async ev=>{const form=ev.target;if(form.matches('[data-config]')){ev.preventDefault();await generate(form)}if(form.id==='block-form'){ev.preventDefault();const f=new FormData(form);const e={id:'custom-'+crypto.randomUUID(),title:String(f.get('title')).trim(),date:f.get('day'),start:f.get('start'),end:f.get('end'),type:'custom',room:''};if(!e.title||e.start>=e.end){toast(t('Geçerli bir başlık ve saat aralığı gir.','Enter a valid title and time interval.'));return}const av=state.profile.availability[e.date];if(!av.enabled||e.start<av.start||e.end>av.end){toast(t('Kişisel zaman katılım saatlerin içinde olmalı.','Personal time must be inside your attendance hours.'));return}const conflicts=planItems().filter(x=>overlaps(e,x,0));if(conflicts.some(x=>x.type==='custom')){toast(t('Başka bir kişisel zamanla çakışıyor.','Conflicts with another personal block.'));return}const commit=()=>{const ids=conflicts.map(x=>x.id);state.plan=state.plan.filter(id=>!ids.includes(id));state.pinned=state.pinned.filter(id=>!ids.includes(id));state.blocks.push(e);state.plan.push(e.id);state.built=true;save();closeDialog('profile');render()};if(conflicts.length)showConfirmation(t('Bu zamanı ayırmak için','To reserve this time'),`<p>${t('Şu seçimler planından çıkarılacak:','These choices will be removed:')}</p>${conflicts.map(x=>`<p class="conflict-item">${esc(title(x,state.lang))}</p>`).join('')}`,commit);else commit()}});
listen('input',ev=>{if(ev.target.id==='search'){state.q=ev.target.value;state.allDays=!!state.q;renderResults();document.querySelectorAll('.day').forEach(x=>x.classList.toggle('active',!state.allDays&&x.dataset.day===state.day));document.querySelector('[data-action=all-days]')?.classList.toggle('active',state.allDays)}if(ev.target.id==='speaker-search'){state.q=ev.target.value;renderSpeakers()}});
listen('change',ev=>{const id=ev.target.id;if(id==='topic-filter')state.topic=ev.target.value;else if(id==='room-filter')state.room=ev.target.value;else if(id==='type-filter')state.type=ev.target.value;else return;renderResults()});
listen('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;if(a==='nav'){state.view=b.dataset.view;track('section_view',{section:state.view});state.q='';render();window.scrollTo({top:0})}else if(a==='language'){for(const d of document.querySelectorAll('dialog[open]'))d.close();state.lang=state.lang==='tr'?'en':'tr';track('language_changed',{language:state.lang});save();render()}else if(a==='day'){state.day=b.dataset.day;state.allDays=false;render()}else if(a==='all-days'){state.allDays=!state.allDays;render()}else if(a==='clear-filters'){state.q='';state.topic='';state.room='';state.type='';render()}else if(a==='detail')detail(id);else if(a==='speaker')speakerDetail(id);else if(a==='add')addSession(id);else if(a==='remove')removeSession(id);else if(a==='pin'){if(state.pinned.includes(id))state.pinned=state.pinned.filter(x=>x!==id);else state.pinned.push(id);state.reasons[id]=state.pinned.includes(id)?{reason:'pinned'}:evaluate(byId[id],state.profile);save();render()}else if(a==='alternatives')alternatives(id);else if(a==='profile')profileDialog();else if(a==='block')blockDialog();else if(a==='remove-block'){state.blocks=state.blocks.filter(x=>x.id!==id);state.plan=state.plan.filter(x=>x!==id);save();render()}else if(a==='preset'){track('preset_selected',{preset:b.dataset.preset});applyPreset(b.dataset.preset,b.closest('form'));}else if(a==='close-dialog')b.closest('dialog').close();else if(a==='cancel-confirm'){pendingAction=null;closeDialog('confirm')}else if(a==='confirm-action'){closeDialog('confirm');let fn=pendingAction;pendingAction=null;fn?.()}else if(a==='export'){track('calendar_download',{event_count:planItems().filter(e=>e.type!=='break').length});download(slug+'-'+t('programim','my-plan')+'.ics',makeICS(planItems(),state.lang,{offset:conf.utcOffset,calendarName:L(conf.name),uidDomain:slug+'.conference-compass'}),'text/calendar;charset=utf-8');toast(t('Takvim dosyan indirildi.','Your calendar file was downloaded.'))}else if(a==='print'){track('print_plan',{event_count:planItems().length});window.print()}else if(a==='download-data'){track('program_download');download(slug+'-program.json',JSON.stringify(data,null,2),'application/json');}else if(a==='reset')showConfirmation(t('Bu cihazdaki plan sıfırlansın mı?','Reset the plan on this device?'),`<p>${t('Kişisel tercihler, sabit seçimler ve plan bu tarayıcıdan kaldırılacak. Resmî program korunur.','Preferences, pinned choices and your plan will be removed from this browser. The official programme remains.')}</p>`,()=>{localStorage.removeItem(STORE);location.reload()},t('Sıfırla','Reset'))});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
render();initAnalytics();subscribeAI(status=>{aiStatus=status;document.querySelectorAll('#ai-state').forEach(x=>x.textContent=statusText())});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
const mc=document.modelContext;if(mc?.registerTool){const controller=new AbortController();const tools=[{name:'search_conference_program',description:'Read the published conference sessions matching a query. Does not alter the personal plan.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw Error('Invalid query');return events.filter(e=>queryMatch(e.search,query)).slice(0,30).map(e=>({id:e.id,title:title(e,state.lang),date:e.date,start:e.start,end:e.end,room:e.room}))}},{name:'read_personal_plan',description:'Read the current personal itinerary without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>planItems().map(e=>({id:e.id,title:e.type==='custom'?e.title:title(e,state.lang),date:e.date,start:e.start,end:e.end}))}];for(const tool of tools)Promise.resolve(mc.registerTool(tool,{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
